		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;

//BLAS PARAMS
//TRANSA = 'N'
//TRANSB = 'N'
// => Form C := alpha*A*B + beta*C,
//A is NIxNK
//B is NKxNJ
//C is NIxNJ
#pragma scop
#define T_I 64
#define T_J 64
#define T_K 64
  int ii, jj, kk;
#pragma omp parallel for private(i, j, k, ii, jj, kk) schedule(static)
  for (ii = 0; ii < _PB_NI; ii += T_I) {
    int i_max = (ii + T_I < _PB_NI) ? (ii + T_I) : _PB_NI;
    for (jj = 0; jj < _PB_NJ; jj += T_J) {
      int j_max = (jj + T_J < _PB_NJ) ? (jj + T_J) : _PB_NJ;
      for (i = ii; i < i_max; i++)
        for (j = jj; j < j_max; j++)
          C[i][j] *= beta;
      for (kk = 0; kk < _PB_NK; kk += T_K) {
        int k_max = (kk + T_K < _PB_NK) ? (kk + T_K) : _PB_NK;
        for (k = kk; k < k_max; k++) {
          DATA_TYPE a_ik = alpha * A[i][k];
          for (i = ii; i < i_max; i++) {
            for (j = jj; j < j_max; j++)
              C[i][j] += a_ik * B[k][j];
          }
        }
      }
    }
  }
#undef T_I
#undef T_J
#undef T_K
#pragma endscop

